<template>
  <div ref="body" class="bg-rice-white">
    <nav-bar ref="navBar" />
    <slide-show />
    <div class="container content-height">
      <div class="row justify-content-center pt-lg-md">
        <div class="col pt-lg-3 pt-0">
          <router-view />
        </div>
      </div>
    </div>
    <footer-area />
    <a class="backToTop" href="#" v-if="showScrollTop" @click.prevent="scrollToTop"
      ><i class="bi bi-arrow-up-circle-fill"></i
    ></a>
  </div>
  <toast-messages />
</template>

<script>
import NavBar from '@/components/front/NavBar.vue'
import SlideShow from '@/components/front/SlideShow.vue'
import FooterArea from '@/components/front/FooterArea.vue'
import ToastMessages from '@/components/back/ToastMessages.vue'
import emitter from '@/methods/emitter'
import _ from 'lodash'

export default {
  components: {
    SlideShow,
    NavBar,
    FooterArea,
    ToastMessages
  },
  data() {
    return {
      num: '',
      moveDelay: {
        transitionDelay: '0s'
      },
      showScrollTop: false
    }
  },
  provide() {
    return {
      emitter
    }
  },
  methods: {
    cartNum(num) {
      this.num = num
    },
    handleScroll() {
      this.showScrollTop = window.scrollY > window.innerHeight / 2
    },
    scrollToTop() {
      window.scrollTo({
        top: 0,
        behavior: 'smooth'
      })
    }
  },
  mounted() {
    window.addEventListener('scroll', _.throttle(this.handleScroll, 200))
  }
}
</script>

<style>
.pt-lg-md {
  padding-top: 3rem !important;
}
.content-height {
  min-height: calc(100vh - 110px);
}
@media (min-width: 1400px) {
  .container {
    max-width: 1170px !important;
  }
}
@media (max-width: 991px) {
  .pt-4-5 {
    padding-top: 1.5rem !important;
  }
}
@media (max-width: 767px) {
  .content-height {
    min-height: calc(100vh - 166px);
  }
}
</style>
